import { ARCHIVED_ERROR, NAME_PATTERN, SHARE_NAME_ERROR, SHARE_SELF_ERROR } from '#shared/types/note'

/** Gives another user read access; only the owner may share, and only notes on their list. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const name = currentUser(event)
  if (!name) {
    if (form) return sendRedirect(event, '/login', 303)
    throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  }
  const id = getRouterParam(event, 'id') ?? ''
  const existing = findNote(name, id)
  if (!existing) {
    if (form) return sendRedirect(event, '/notes', 303)
    throw createError({ statusCode: 404, statusMessage: 'Note not found' })
  }
  if (existing.archived) {
    if (form) return sendRedirect(event, '/archive', 303)
    throw createError({ statusCode: 409, statusMessage: ARCHIVED_ERROR, data: { code: 'archived' } })
  }
  const body = await readBody<{ name?: unknown }>(event)
  const recipient = typeof body?.name === 'string' ? body.name.trim() : ''
  const fail = (code: string) => sendRedirect(event, `/notes?share=${encodeURIComponent(id)}&shareError=${code}`, 303)
  if (!NAME_PATTERN.test(recipient)) {
    if (form) return fail('invalid')
    throw createError({ statusCode: 400, statusMessage: SHARE_NAME_ERROR, data: { code: 'invalid' } })
  }
  if (sameUser(name, recipient)) {
    if (form) return fail('self')
    throw createError({ statusCode: 400, statusMessage: SHARE_SELF_ERROR, data: { code: 'self' } })
  }
  shareNote(name, id, recipient)
  if (form) return sendRedirect(event, '/notes', 303)
  return { id, sharedWith: sharedWith(id) }
})

