import { isAdmin } from '#shared/types/note'

/** Makes another user's account read-only or writable again; only the admin may do this, and never to itself. */
export default defineEventHandler(async (event) => {
  const form = isFormPost(event)
  const adminName = currentUser(event)
  if (!adminName || !isAdmin(adminName)) {
    if (form) return sendRedirect(event, '/admin', 303)
    throw createError({ statusCode: 403, statusMessage: 'Forbidden' })
  }
  const body = await readBody<{ name?: unknown; readOnly?: unknown }>(event)
  const target = typeof body?.name === 'string' ? body.name.trim() : ''
  const readOnly = body?.readOnly === true || body?.readOnly === 'true'
  if (target && !isAdmin(target)) setReadOnly(target, readOnly)
  if (form) return sendRedirect(event, '/admin', 303)
  return { name: target, readOnly }
})

