async function toggleAccess(user: { name: string; readOnly: boolean }) {
  if (updating.value) return
  updating.value = user.name
  try {
    await $fetch('/api/admin/access', { method: 'POST', body: { name: user.name, readOnly: !user.readOnly } })
  } catch (error) {
    if ((error as { statusCode?: number }).statusCode === 401) return navigateTo('/login')
  } finally {
    updating.value = null
  }
  await refresh()
}

