import type { NotesResponse } from '#shared/types/note'

export default defineEventHandler((event): NotesResponse => {
  const name = currentUser(event)
  if (!name) return { name, notes: [], deletedTitle: null }
  return {
    name,
    notes: listNotes(name).map((note) => ({ ...note, sharedWith: sharedWith(note.id) })),
    deletedTitle: lastDeleted(name)?.title ?? null,
    shared: listSharedWith(name),
  }
})

